import{_ as n,I as i,o as d,c as l,j as t,a as o,J as r,a6 as s}from"./chunks/framework.9ylqSDY5.js";const w=JSON.parse('{"title":"Observer Console","description":"","frontmatter":{"title":"Observer Console","visibility":"public","audience":"astronomer","tier":"guide","source":"handwritten"},"headers":[],"relativePath":"guides/observing/observer-console.md","filePath":"guides/observing/observer-console.md"}'),h={name:"guides/observing/observer-console.md"};function c(g,e,u,f,p,b){const a=i("ToolShot");return d(),l("div",null,[e[0]||(e[0]=t("h1",{id:"observer-console",tabindex:"-1"},[o("Observer Console "),t("a",{class:"header-anchor",href:"#observer-console","aria-label":"Permalink to “Observer Console”"},"​")],-1)),e[1]||(e[1]=t("p",null,[t("strong",null,"A whole night by hand, in one frame."),o(" Point, focus, guide, expose and review without changing screen.")],-1)),r(a,{tool:"observer-console"}),e[2]||(e[2]=s('<h2 id="what-it-is-for" tabindex="-1">What it is for <a class="header-anchor" href="#what-it-is-for" aria-label="Permalink to “What it is for”">​</a></h2><ul><li>Observe manually with one setup.</li><li>Take a queue of exposures, or a mosaic, on the current target.</li><li>Inspect frames as they land, with guiding and sky conditions in view.</li></ul><p>For a night that runs on its own, use the <a href="./night-scheduler">Night Scheduler</a>.</p><h2 id="reading-the-console" tabindex="-1">Reading the console <a class="header-anchor" href="#reading-the-console" aria-label="Permalink to “Reading the console”">​</a></h2><p>From top to bottom:</p><table tabindex="0"><thead><tr><th>Area</th><th>What it shows</th></tr></thead><tbody><tr><td><strong>Night</strong></td><td>The airmass curve of the target with the time and the hourly weather, the sky as the telescope sees it, its coordinates and the state of the dome</td></tr><tr><td><strong>Session controls</strong></td><td>Target, telescope, camera, filter wheel, rotator, focuser and dome, each with its commands</td></tr><tr><td><strong>Safety line</strong></td><td>The current GO or NOGO, and the <strong>Emergency Stop</strong></td></tr><tr><td><strong>Preview</strong></td><td>The <strong>Queue</strong> and <strong>Review</strong> tabs, above a gallery of the night&#39;s frames</td></tr><tr><td><strong>Side panels</strong></td><td>Guiding, sky conditions and equipment parameters, opened as needed</td></tr></tbody></table><h2 id="a-typical-observation" tabindex="-1">A typical observation <a class="header-anchor" href="#a-typical-observation" aria-label="Permalink to “A typical observation”">​</a></h2><ol><li>Choose the observing setup in the status bar and take control of it.</li><li>Pick a <strong>target</strong>, enter coordinates, or take one from a <a href="./night-studio#target-lists">target list</a>.</li><li><strong>Slew</strong>, then <strong>Center...</strong> to refine the pointing by plate solving.</li><li>Choose a filter, and run <strong>Find Focus...</strong>.</li><li>Start guiding from the Guiding panel.</li><li>Set the exposure time and count, then <strong>Start</strong>.</li></ol><h2 id="what-is-checked-before-an-exposure" tabindex="-1">What is checked before an exposure <a class="header-anchor" href="#what-is-checked-before-an-exposure" aria-label="Permalink to “What is checked before an exposure”">​</a></h2><p>The console stops and asks rather than take a frame that would be lost:</p><table tabindex="0"><thead><tr><th>It finds that…</th><th>It proposes to…</th></tr></thead><tbody><tr><td>The telescope is off target</td><td>Slew first, then start, or start anyway</td></tr><tr><td>A moving target will trail during the exposure</td><td>Shorten it, or expose anyway. Non-sidereal tracking makes the mount follow the target</td></tr><tr><td>The exposure would cross the meridian</td><td>Flip, then start</td></tr><tr><td>The sequence will reach the meridian</td><td>Flip automatically when it is due, and carry on</td></tr></tbody></table><h2 id="queue-and-mosaics" tabindex="-1">Queue and mosaics <a class="header-anchor" href="#queue-and-mosaics" aria-label="Permalink to “Queue and mosaics”">​</a></h2><p>In the <strong>Queue</strong> tab, each row is a series of exposures with its filter and rotator angle. <strong>Run queue</strong> takes them in order. The field is shown beside the queue, on your finding charts or on Aladin.</p><p><strong>Add a mosaic</strong> lays out a grid of tiles on the field: choose the grid, the overlap, the scan order and the filters. Each tile becomes a row, and what is drawn is exactly what is shot.</p>',14)),r(a,{tool:"observer-console",index:1}),e[3]||(e[3]=s('<h2 id="review" tabindex="-1">Review <a class="header-anchor" href="#review" aria-label="Permalink to “Review”">​</a></h2><p>The <strong>Review</strong> tab opens a frame as soon as it arrives: scale, colour map, background, noise, saturation, number of stars, HFR and FWHM, a close-up, and the full FITS header. The gallery is filtered by kind: science, calibration, autofocus, plate solving.</p><h2 id="safety" tabindex="-1">Safety <a class="header-anchor" href="#safety" aria-label="Permalink to “Safety”">​</a></h2><p>The safety line shows the verdict of each condition set (see <a href="./safety-configuration">Safety Configuration</a>). <strong>Emergency Stop</strong> launches the site&#39;s Fail-Safe Shutdown. When the line says the verdict is unknown, nothing has been evaluated in the last hour: it does not mean that all is well.</p>',4))])}const v=n(h,[["render",c]]);export{w as __pageData,v as default};
